from scipy.signal import fftconvolve


def _score(h):
    """Exact R for step heights h, using knot values L=[0, *conv(h,h), 0]."""
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _build(beta, b, N):
    """Cell averages of f(t)=t^{-1/2}(1-t)^{-beta}(1+b t) on [0,1], N cells."""
    # Sample at cell midpoints (cell averages approximated by midpoint; fine at large N).
    t = (np.arange(N, dtype=float) + 0.5) / N
    h = t ** (-0.5)
    if abs(beta) > 1e-12:
        h = h * (1.0 - t) ** (-beta)
    if abs(b) > 1e-12:
        h = h * (1.0 + b * t)
    return h


