    deadline = budget_seconds - 0.5

    best_h = None
    best_r = -1.0

    def try_params(beta, b, N):
        nonlocal best_h, best_r
        h = _build(beta, b, N)
        r = _score(h)
        if r > best_r:
            best_r = r
            best_h = h
        return r

    # Include start as fallback.
