import numpy as np
import time
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _score(h):
    """Exact R for step heights h, using knot values L=[0, *conv(h,h), 0]."""
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _build(alpha, N):
    """Cell-average heights of t^{-alpha} on [0,1]."""
    i = np.arange(N, dtype=float)
    if abs(1.0 - alpha) < 1e-12:
        return np.ones(N)
    p = 1.0 - alpha
    return ((i + 1.0) ** p - i ** p) / p


def _cheb_basis(t, K):
    """Chebyshev T_k(2t-1) for k=1..K, shape (K, len(t))."""
    x = 2.0 * t - 1.0
    B = np.empty((K, t.size))
    if K >= 1:
        B[0] = x
    if K >= 2:
        B[1] = 2.0 * x * x - 1.0
    for k in range(2, K):
        B[k] = 2.0 * x * B[k - 1] - B[k - 2]
    return B


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.0

    N = 50000
    K = 15
    t = (np.arange(N, dtype=float) + 0.5) / N
    log_base = -0.5 * np.log(t)
    B = _cheb_basis(t, K)  # (K, N)

    best_h = None
    best_r = -1.0

    def record(h, r):
        nonlocal best_h, best_r
        if r > best_r:
            best_r = r
            best_h = h.copy()

    # Baseline: pure power law alpha=0.5 at this N.
    h0 = np.exp(log_base)
    r0 = _score(h0)
    record(h0, r0)

    # Also consider the provided start (may be a different N).
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            record(s, _score(s))

    # Objective in terms of c (length K), with c=0 => power law.
    def make_h(c):
        c = np.asarray(c, dtype=float)
        logh = log_base + c @ B
        # guard against overflow
        logh = np.clip(logh, -50.0, 50.0)
        return np.exp(logh)

    def neg_obj(c):
        h = make_h(c)
        return -_score(h)

    # Nelder-Mead with time-limited callback.
    c0 = np.zeros(K)
    state = {'best_c': c0.copy(), 'best_r': r0}

    def callback(xk):
        # Evaluate and record; stop when out of time.
        r = _score(make_h(xk))
        if r > state['best_r']:
            state['best_r'] = r
            state['best_c'] = np.array(xk, dtype=float)
            record(make_h(xk), r)
        if time.process_time() - t0 > deadline:
            raise StopIteration

    try:
        res = minimize(
            neg_obj, c0, method='Nelder-Mead',
            options={'maxiter': 100000, 'xatol': 1e-6, 'fatol': 1e-9,
                     'adaptive': True},
            callback=callback,
        )
        if res is not None and res.x is not None:
            h = make_h(res.x)
            record(h, _score(h))
    except StopIteration:
        pass
    except Exception:
        pass

    # If time remains, do coordinate descent refinement on c from best.
    if time.process_time() - t0 < deadline:
        c = state['best_c'].copy()
        cur_r = _score(make_h(c))
        step = 0.05
        while step > 1e-4 and time.process_time() - t0 < deadline:
            improved = False
            for k in range(K):
                if time.process_time() - t0 > deadline:
                    break
                for sgn in (1.0, -1.0):
                    if time.process_time() - t0 > deadline:
                        break
                    trial = c.copy()
                    trial[k] += sgn * step
                    h = make_h(trial)
                    r = _score(h)
                    if r > cur_r + 1e-12:
                        c = trial
                        cur_r = r
                        record(h, r)
                        improved = True
                        break
            if not improved:
                step *= 0.5

    if best_h is None:
        return np.ones(50)
    return np.asarray(best_h, dtype=float)

