    x = 2.0 * t - 1.0
    B = np.empty((K, t.size))
    if K >= 1:
        B[0] = x
    if K >= 2:
        B[1] = 2.0 * x * x - 1.0
    for k in range(2, K):
        B[k] = 2.0 * x * B[k - 1] - B[k - 2]
    return B


def _resample(start, N):
    """Resample start to N cells by cell-midpoint interpolation."""
    s = np.asarray(start, dtype=float)
    M = s.size
    if M == N:
        return s.copy()
    # cell midpoints of source and target in [0,1]
    src = (np.arange(M, dtype=float) + 0.5) / M
    dst = (np.arange(N, dtype=float) + 0.5) / N
    return np.interp(dst, src, s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.0

    best_h = None
    best_r = -1.0

    def record(h, r):
        nonlocal best_h, best_r
        if r > best_r:
            best_r = r
            best_h = np.asarray(h, dtype=float).copy()

    # --- Baseline: pure power law alpha=0.5 at N=50000 ---
    N0 = 50000
    K = 15
    t = (np.arange(N0, dtype=float) + 0.5) / N0
