            neg_obj, c0, method='Nelder-Mead',
            options={'maxiter': 100000, 'xatol': 1e-6, 'fatol': 1e-9,
                     'adaptive': True},
            callback=callback,
        )
        if res is not None and res.x is not None:
            h = make_h(res.x)
            record(h, _score(h))
    except StopIteration:
        pass
    except Exception:
        pass

