                        break
                    trial = c.copy()
                    trial[k] += sgn * step
                    h = make_h(trial)
                    r = _score(h)
                    if r > cur_r + 1e-12:
                        c = trial
                        cur_r = r
                        record(h, r)
                        improved = True
                        break
