            record(h, cur_r)

            rng = np.random.default_rng(12345)
            blocks = [8000, 2000, 500, 100, 20]
            deltas = [0.02, 0.01, 0.005, 0.002, 0.001, 5e-4, 2e-4, 1e-4]

