        except Exception:
            pass

    if best_h is None:
        return np.ones(50)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _score(h):
    """Exact R for step heights h, using knot values L=[0, *conv(h,h), 0]."""
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _build(alpha, beta, b, c, N):
    """h_i = A_i * (1-t_i)^{-beta} * (1 + b t_i + c t_i^2), t_i=(i+0.5)/N,
    A_i = exact cell average of t^{-alpha} on [i/N,(i+1)/N]."""
    i = np.arange(N, dtype=float)
    t = (i + 0.5) / N
    # Exact cell average of t^{-alpha}
    if abs(alpha - 1.0) < 1e-12:
        A = np.ones(N)
    else:
        A = ((i + 1.0) ** (1.0 - alpha) - i ** (1.0 - alpha)) / (1.0 - alpha)
    h = A
    if abs(beta) > 1e-12:
        h = h * (1.0 - t) ** (-beta)
    if abs(b) > 1e-12 or abs(c) > 1e-12:
        h = h * (1.0 + b * t + c * t * t)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.0

    best_h = None
    best_r = -1.0

    def consider(h):
        nonlocal best_h, best_r
        h = np.asarray(h, dtype=float)
        if h.size == 0 or not np.all(np.isfinite(h)) or not np.any(h > 0):
            return -1.0
        r = _score(h)
        if r > best_r:
            best_r = r
            best_h = h.copy()
        return r

    # Start as fallback.
    if start is not None:
        consider(start)

    # Stage 1: coarse scan at N=20000.
    N1 = 20000
    alphas = np.arange(0.45, 0.55 + 1e-9, 0.01)
    betas = np.arange(-0.1, 0.4 + 1e-9, 0.05)
    bs = np.arange(-0.5, 0.5 + 1e-9, 0.25)
    cs = np.arange(-0.5, 0.5 + 1e-9, 0.25)

    best_params = [0.5, 0.0, 0.0, 0.0]
    best_r1 = -1.0
    for alpha in alphas:
        if time.process_time() - t0 > deadline * 0.35:
            break
        for beta in betas:
            for b in bs:
                for c in cs:
                    if time.process_time() - t0 > deadline * 0.35:
                        break
                    h = _build(alpha, beta, b, c, N1)
                    r = _score(h)
                    if r > best_r1:
                        best_r1 = r
                        best_params = [alpha, beta, b, c]
                    consider(h)
                else:
                    continue
                break
            else:
                continue
            break

    # Stage 2: Nelder-Mead refine at N=100000.
    def obj(p, N):
        alpha, beta, b, c = p
        # Keep parameters in sane ranges.
        if not (0.3 < alpha < 0.7 and -0.5 < beta < 0.9):
            return 1.0
        h = _build(alpha, beta, b, c, N)
        return -_score(h)

    N2 = 100000
    p = np.array(best_params, dtype=float)
    if time.process_time() - t0 < deadline * 0.7:
        res = minimize(obj, p, args=(N2,), method='Nelder-Mead',
                       options={'xatol': 1e-4, 'fatol': 1e-7,
                                'maxiter': 400, 'maxfev': 800,
                                'initial_simplex': None})
        if -res.fun > best_r1:
            p = res.x
        consider(_build(p[0], p[1], p[2], p[3], N2))

    # Stage 3: Nelder-Mead refine at N=200000.
    N3 = 200000
    if time.process_time() - t0 < deadline:
        # time-limited wrapper
        def obj3(q):
            if time.process_time() - t0 > deadline:
                return 1.0
            return obj(q, N3)
        res = minimize(obj3, p, method='Nelder-Mead',
                       options={'xatol': 1e-5, 'fatol': 1e-8,
                                'maxiter': 300, 'maxfev': 600})
        q = res.x
        consider(_build(q[0], q[1], q[2], q[3], N3))
        p = q

    # Final: rebuild best params at N3 if time remains.
    if time.process_time() - t0 < deadline:
        consider(_build(p[0], p[1], p[2], p[3], N3))

    if best_h is None:
        return np.ones(50)
    return np.asarray(best_h, dtype=float)
